--[[
	DungeonRoom

	字段列表:
		ID {int} 编号
		TerrainId* {int} 地形ID
		Type* {int} 类型
		Exclusive {int} 相邻排斥组
		Weight* {int} 刷新权重
		DistanceWeight {int} 距离加权
		MathBossRoom {bool} 计见BOSS房间数
		MakeBless {array(int, int...)} 生成祝福库|数量
		PassSpawn {array(array(auto, auto...), ...)} 通关刷(spawnid)
		Difficulty* {array(int, int...)} 难度区间
		BurnLevel* {array(int, int...)} 燃烧等级区间
		Layer* {array(int, int...)} 层数限制
		BindSkill {int} 绑定技能
		TimeId {int} 时间ID
		TransferRotate {int} 传送门旋转
		MaxLimit {int} 最大限制
		ShowPet {bool} 显示随从
		ScriptsExtend {int} 数据继承（复用其他房间数据）
		Scripts.Index* {int} 序号
		Scripts.SubDifficulty* {array(int, int...)} 难度区间
		Scripts.SubBurnLevel* {array(int, int...)} 燃烧等级区间
		Scripts.SubLayer* {array(int, int...)} 层数限制
		Scripts.SubRoom* {array(int, int...)} 经过房间数
		Scripts.SubTimeId {int} 赛季
		Scripts.SubActivityId {int} 活动ID
		Scripts.Precondition {int} 前置脚本
		Scripts.Odds* {int} 出现概率(万分比)
		Scripts.Delay {number} 延时执行脚本/s
		Scripts.TypeName* {string} 脚本名称
		Scripts.Params {array(array(auto, auto...), ...)} 脚本参数

]]
